package me.ehsan.morghchat;

import me.ehsan.morghchat.alerts.AlertManager;
import me.ehsan.morghchat.channels.GlobalChatManager;
import me.ehsan.morghchat.channels.GlobalChatManager.Channel;
import me.ehsan.morghchat.chatcolor.ChatColorCommand;
import me.ehsan.morghchat.chatcolor.ChatColorListener;
import me.ehsan.morghchat.chatcolor.ChatColorManager;
import me.ehsan.morghchat.commands.*;
import me.ehsan.morghchat.filter.CapsManager;
import me.ehsan.morghchat.filter.FilterManager;
import me.ehsan.morghchat.interactive.InteractiveChatListener;
import me.ehsan.morghchat.interactive.InteractiveChatManager;
import me.ehsan.morghchat.listeners.ChatListener;
import me.ehsan.morghchat.listeners.PlayerStateListener;
import me.ehsan.morghchat.messages.MessagesManager;
import me.ehsan.morghchat.messaging.IgnoreManager;
import me.ehsan.morghchat.messaging.PrivateMessageManager;
import me.ehsan.morghchat.muting.MuteManager;
import me.ehsan.morghchat.network.NetworkMessenger;
import me.ehsan.morghchat.spy.SpyInputListener;
import me.ehsan.morghchat.spy.SpyListener;
import me.ehsan.morghchat.spy.SpyManager;
import me.ehsan.morghchat.storage.MySqlStorage;
import org.bukkit.ChatColor;
import org.bukkit.command.PluginCommand;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.permissions.Permission;
import org.bukkit.permissions.PermissionDefault;
import org.bukkit.plugin.java.JavaPlugin;

public final class MorghChat extends JavaPlugin {
    private static MorghChat instance; private NetworkMessenger networkMessenger; private GlobalChatManager globalChatManager; private FilterManager filterManager; private AlertManager alertManager; private CapsManager capsManager; private PrivateMessageManager messageManager; private IgnoreManager ignoreManager; private MuteManager muteManager; private SpyManager spyManager; private ChatColorManager chatColorManager; private MessagesManager messagesManager; private InteractiveChatManager interactiveChatManager; private MySqlStorage storage; private FileConfiguration config;
    @Override public void onEnable(){instance=this;loadPluginConfig();messagesManager=new MessagesManager(this);storage=new MySqlStorage(this);networkMessenger=new NetworkMessenger(this);muteManager=new MuteManager(this);globalChatManager=new GlobalChatManager(this);alertManager=new AlertManager(this);filterManager=new FilterManager(this);capsManager=new CapsManager(this);messageManager=new PrivateMessageManager(this);ignoreManager=new IgnoreManager(this);spyManager=new SpyManager(this);chatColorManager=new ChatColorManager(this);interactiveChatManager=new InteractiveChatManager(this);registerChatColorPermissions();registerInteractivePermissions();getServer().getPluginManager().registerEvents(new ChatListener(this),this);getServer().getPluginManager().registerEvents(new SpyListener(this),this);getServer().getPluginManager().registerEvents(new SpyInputListener(this),this);getServer().getPluginManager().registerEvents(new PlayerStateListener(this),this);getServer().getPluginManager().registerEvents(new InteractiveChatListener(this),this);getCommand("msg").setExecutor(new MsgCommand(this));getCommand("reply").setExecutor(new ReplyCommand(this));IgnoreCommand ignoreCmd=new IgnoreCommand(this);getCommand("ignore").setExecutor(ignoreCmd);getCommand("unignore").setExecutor(ignoreCmd);getCommand("channel").setExecutor(new ChannelCommand(this));getCommand("channelmutelist").setExecutor(new ChannelMuteListCommand(this));MuteCommand muteCommand=new MuteCommand(this);getCommand("mute").setExecutor(muteCommand);getCommand("unmute").setExecutor(muteCommand);getCommand("clearchat").setExecutor(new ClearChatCommand(this));getCommand("morghchat").setExecutor(new MorghChatCommand(this));getCommand("chat").setExecutor(new ChatChannelCommand(this,null));getCommand("chathide").setExecutor(new ChatHideCommand(this));getCommand("staffchat").setExecutor(new ChatChannelCommand(this,Channel.STAFF));getCommand("donatorchat").setExecutor(new ChatChannelCommand(this,Channel.DONATOR));getCommand("adminchat").setExecutor(new ChatChannelCommand(this,Channel.ADMIN));getCommand("highrankchat").setExecutor(new ChatChannelCommand(this,Channel.HIGHRANK));getCommand("gc").setExecutor(new ChatChannelCommand(this,Channel.GLOBAL));getCommand("spy").setExecutor(new SpyCommand(this));getCommand("stafflist").setExecutor(new ChannelListCommand(this,Channel.STAFF));getCommand("highranklist").setExecutor(new ChannelListCommand(this,Channel.HIGHRANK));getCommand("adminlist").setExecutor(new ChannelListCommand(this,Channel.ADMIN));getCommand("donatorlist").setExecutor(new ChannelListCommand(this,Channel.DONATOR));ChatColorCommand chatColorCommand=new ChatColorCommand(chatColorManager);getCommand("chatcolor").setExecutor(chatColorCommand);getServer().getPluginManager().registerEvents(new ChatColorListener(this,chatColorManager,chatColorCommand),this);MorghChatTabCompleter completer=new MorghChatTabCompleter();String[] completable={"msg","ignore","unignore","channel","channelmutelist","mute","unmute","clearchat","chathide","chat","spy","morghchat","chatcolor","stafflist","highranklist","adminlist","donatorlist"};for(String commandName:completable){PluginCommand command=getCommand(commandName);if(command!=null)command.setTabCompleter(completer);}printEnableBanner();}
    private void registerChatColorPermissions(){registerPermission("morghchat.chatcolor.color.*","Allows every Chat Color color",PermissionDefault.FALSE);registerPermission("morghchat.chatcolor.gradient.*","Allows every Chat Color gradient",PermissionDefault.FALSE);registerPermission("morghchat.chatcolor.style.*","Allows every Chat Color style",PermissionDefault.FALSE);registerPermission("morghchat.chatcolor.custom.*","Allows every Chat Color custom formatting option",PermissionDefault.FALSE);registerPermission("morghchat.chatcolor.custom","Allows custom MiniMessage chat formatting",PermissionDefault.FALSE);for(String color:ChatColorManager.COLORS)registerPermission("morghchat.chatcolor.color."+color,"Allows the "+color+" chat color",PermissionDefault.FALSE);for(String gradient:ChatColorManager.GRADIENTS)registerPermission("morghchat.chatcolor.gradient."+gradient,"Allows the "+gradient+" chat gradient",PermissionDefault.FALSE);for(String style:ChatColorManager.STYLES)registerPermission("morghchat.chatcolor.style."+style,"Allows the "+style+" chat style",PermissionDefault.FALSE);}
    private void registerInteractivePermissions(){registerPermission("morghchat.interactive.*","Allows every MorghChat interactive chat feature",PermissionDefault.TRUE);registerPermission("morghchat.interactive.item","Allows using item placeholders",PermissionDefault.TRUE);registerPermission("morghchat.interactive.inventory","Allows inventory placeholders",PermissionDefault.TRUE);registerPermission("morghchat.interactive.ender","Allows ender placeholders",PermissionDefault.TRUE);registerPermission("morghchat.interactive.player","Allows interactive player handling",PermissionDefault.TRUE);registerPermission("morghchat.interactive.commands","Allows interactive command links",PermissionDefault.TRUE);registerPermission("morghchat.interactive.position","Allows position placeholder",PermissionDefault.TRUE);registerPermission("morghchat.interactive.ping","Allows ping placeholder",PermissionDefault.TRUE);registerPermission("morghchat.interactive.custom.*","Allows configured custom placeholders",PermissionDefault.FALSE);registerPermission("morghchat.interactive.custom","Allows configured custom placeholders",PermissionDefault.FALSE);}
    private void registerPermission(String name,String description,PermissionDefault defaultValue){if(getServer().getPluginManager().getPermission(name)==null)getServer().getPluginManager().addPermission(new Permission(name,description,defaultValue));}
    @Override public void onDisable(){if(muteManager!=null)muteManager.save();if(ignoreManager!=null)ignoreManager.save();if(spyManager!=null)spyManager.save();if(chatColorManager!=null)chatColorManager.save();if(storage!=null)storage.flush();if(networkMessenger!=null)networkMessenger.close();if(storage!=null)storage.shutdown();getServer().getConsoleSender().sendMessage(ChatColor.GOLD+"[MorghChat] "+ChatColor.RED+"Disabled.");}
    public void loadPluginConfig(){saveDefaultConfig();reloadConfig();config=getConfig();if(messagesManager!=null)messagesManager.reload();}
    private void printEnableBanner(){getServer().getConsoleSender().sendMessage("[MorghChat] Plugin enabled.");}
    public static MorghChat getInstance(){return instance;} public NetworkMessenger getNetworkMessenger(){return networkMessenger;}public GlobalChatManager getGlobalChatManager(){return globalChatManager;}public FilterManager getFilterManager(){return filterManager;}public AlertManager getAlertManager(){return alertManager;}public CapsManager getCapsManager(){return capsManager;}public PrivateMessageManager getMessageManager(){return messageManager;}public IgnoreManager getIgnoreManager(){return ignoreManager;}public MuteManager getMuteManager(){return muteManager;}public SpyManager getSpyManager(){return spyManager;}public ChatColorManager getChatColorManager(){return chatColorManager;}public MessagesManager getMessagesManager(){return messagesManager;}public InteractiveChatManager getInteractiveChatManager(){return interactiveChatManager;}public MySqlStorage getStorage(){return storage;}public FileConfiguration getPluginConfig(){return config;}
}
